BEGIN TRANSACTION;

DROP TABLE IF EXISTS "class_names";
CREATE TABLE class_names (
      classId INTEGER NOT NULL,
      languageCode TEXT NOT NULL,
      name TEXT NOT NULL,
      PRIMARY KEY(classId,languageCode),
      FOREIGN KEY(classId) REFERENCES classes(id),
      FOREIGN KEY(languageCode) REFERENCES languages(code)
    );

DROP TABLE IF EXISTS "classes";
CREATE TABLE classes (
      id INTEGER NOT NULL,
      color TEXT NOT NULL,
      code TEXT NOT NULL,
      icon TEXT NOT NULL,
      PRIMARY KEY(id)
    );

DROP TABLE IF EXISTS "dependencies";
CREATE TABLE "dependencies" (
	"talentId"	INTEGER NOT NULL,
	"dependencyId"	INTEGER NOT NULL,
	PRIMARY KEY("talentId","dependencyId")
);

DROP TABLE IF EXISTS "expansion_names";
CREATE TABLE expansion_names (
      expansionId INTEGER NOT NULL,
      languageCode TEXT NOT NULL,
      name TEXT NOT NULL,
      PRIMARY KEY(expansionId,languageCode),
      FOREIGN KEY(expansionId) REFERENCES expansions(id),
      FOREIGN KEY(languageCode) REFERENCES languages(code)
    );

DROP TABLE IF EXISTS "expansions";
CREATE TABLE expansions (
      id INTEGER PRIMARY KEY,
      code TEXT NOT NULL,
      edition TEXT NOT NULL,
      era TEXT
    );

DROP TABLE IF EXISTS "languages";
CREATE TABLE languages (
      code TEXT PRIMARY KEY,
      name TEXT NOT NULL
    );

DROP TABLE IF EXISTS "rank_descriptions";
CREATE TABLE rank_descriptions (
      talentId INTEGER NOT NULL,
      rank INTEGER NOT NULL,
      languageCode TEXT NOT NULL,
      description TEXT NOT NULL,
      PRIMARY KEY(talentId,rank,languageCode),
      FOREIGN KEY(talentId,rank) REFERENCES ranks(talentId,rank),
      FOREIGN KEY(languageCode) REFERENCES languages(code)
    );

DROP TABLE IF EXISTS "ranks";
CREATE TABLE ranks (
      talentId INTEGER NOT NULL,
      rank INTEGER NOT NULL,
      PRIMARY KEY(talentId,rank)
    );

DROP TABLE IF EXISTS "talent_names";
CREATE TABLE talent_names (
      talentId INTEGER NOT NULL,
      languageCode TEXT NOT NULL,
      name TEXT NOT NULL,
      PRIMARY KEY(talentId,languageCode),
      FOREIGN KEY(talentId) REFERENCES talents(id),
      FOREIGN KEY(languageCode) REFERENCES languages(code)
    );

DROP TABLE IF EXISTS "talent_tree_names";
CREATE TABLE "talent_tree_names" (
	"classId"	INTEGER NOT NULL,
	"talentTreeId"	INTEGER NOT NULL,
	"languageCode"	TEXT NOT NULL,
	"name"	TEXT NOT NULL,
	PRIMARY KEY("classId","talentTreeId","languageCode"),
	FOREIGN KEY("classId","talentTreeId") REFERENCES "talent_trees"("classId","id"),
	FOREIGN KEY("languageCode") REFERENCES "languages"("code")
);

DROP TABLE IF EXISTS "talent_trees";
CREATE TABLE "talent_trees" (
	"classId"	INTEGER NOT NULL,
	"id"	INTEGER NOT NULL,
	"icon"	TEXT NOT NULL,
	"background"	TEXT NOT NULL,
	PRIMARY KEY("classId","id")
);

DROP TABLE IF EXISTS "talents";
CREATE TABLE "talents" (
	"classId"	INTEGER NOT NULL,
	"talentTreeId"	INTEGER NOT NULL,
	"id"	INTEGER NOT NULL,
	"row"	INTEGER NOT NULL,
	"column"	INTEGER NOT NULL,
	"icon"	TEXT NOT NULL,
	"dependencyId"	INTEGER,
	"expansion"	INTEGER NOT NULL,
	PRIMARY KEY("id")
);
