(1039, 0, 'en', 'Increases your Armor contribution from cloth and leather items by 4%.'),
(1039, 1, 'en', 'Increases your Armor contribution from cloth and leather items by 7%.'),
(1039, 2, 'en', 'Increases your Armor contribution from cloth and leather items by 10%.'),
(1050, 0, 'en', 'Increases your movement speed by 15% in Cat Form and increases your chance to dodge while in Cat Form, Bear Form and Dire Bear Form by 2%.'),
(1050, 1, 'en', 'Increases your movement speed by 30% in Cat Form and increases your chance to dodge while in Cat Form, Bear Form and Dire Bear Form by 4%.'),
