(1616, 1, 'en', 'Increases your total Stamina by 7%.'),
(1616, 2, 'en', 'Increases your total Stamina by 10%.'),
(1636, 0, 'en', 'You have a 50% chance to heal your pet for 15% of the amount of spell damage done by you.'),
(1636, 1, 'en', 'You have a 100% chance to heal your pet for 15% of the amount of spell damage done by you.'),
(1617, 0, 'en', 'Increases the amount of Health transferred by your Health Funnel spell by 10% and reduces the health cost by 10%. In addition, your summoned Demon takes 15% less damage while under the effect of your Health Funnel.'),
(1617, 1, 'en', 'Increases the amount of Health transferred by your Health Funnel spell by 20% and reduces the health cost by 20%. In addition, your summoned Demon takes 30% less damage while under the effect of your Health Funnel.'),
(1618, 0, 'en', 'Increases the effectiveness of your Voidwalker''s Torment, Consume Shadows, Sacrifice and Suffering spells by 10%, and increases the attack power bonus on your Felguard''s Demonic Frenzy effect by 1%.'),
(1618, 1, 'en', 'Increases the effectiveness of your Voidwalker''s Torment, Consume Shadows, Sacrifice and Suffering spells by 20%, and increases the attack power bonus on your Felguard''s Demonic Frenzy effect by 2%.'),
(1618, 2, 'en', 'Increases the effectiveness of your Voidwalker''s Torment, Consume Shadows, Sacrifice and Suffering spells by 30%, and increases the attack power bonus on your Felguard''s Demonic Frenzy effect by 3%.'),
(1621, 0, 'en', 'Increases the Stamina and Intellect of your Imp, Voidwalker, Succubus, Felhunter and Felguard by 5% and increases your maximum health and mana by 1%.'),
(1621, 1, 'en', 'Increases the Stamina and Intellect of your Imp, Voidwalker, Succubus, Felhunter and Felguard by 10% and increases your maximum health and mana by 2%.'),
(1621, 2, 'en', 'Increases the Stamina and Intellect of your Imp, Voidwalker, Succubus, Felhunter and Felguard by 15% and increases your maximum health and mana by 3%.'),
