INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (492,'de','Baum des Lebens');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (492,0,'de','Verwandelt Euch in die Gestalt eines Baums des Lebens. In dieser Gestalt ist die erhaltene Heilung bei allen Gruppenmitgliedern im Umkreis von 45 Metern um 25% Eurer gesamten Willenskraft erhöht,Euer Bewegungstempo ist um 20% verringert und Ihr könnt nur ''Rasche Heilung'',''Anregen'',''Schnelligkeit der Natur'',''Wiedergeburt'',''Baumrinde'',Gift aufhebende Zauber und Heilzauber,die über einen bestimmten Zeitraum wirken,benutzen. Die Manakosten dieser Zauber sind um 20% verringert.<br /><br />Der Akt des Gestaltwandelns befreit den Zaubernden von verwandlungs- und bewegungseinschränkenden Effekten.');
