INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (652,'de','Heiliger Schild');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (652,0,'de','Erhöht die Blockchance 10 sec lang um 30% und fügt,solange aktiv,für jeden geblockten Angriff 59 Heiligschaden zu. Der durch ''Heiliger Schild'' verursachte Schaden erzeugt 35% zusätzliche Bedrohung. Jedes Blocken verbraucht eine der 4 Aufladungen.');
