INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (677,'de','Siegel des Befehls');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (677,0,'de','Erfüllt den Paladin 30 sec lang mit dem Geist des Befehls und gewährt ihm die Chance,zusätzlich zum erzielten Waffenschaden,Heiligschaden in Höhe von 70% des normalen Waffenschadens zuzufügen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.<br /><br />Die Entfesselung der Energie dieses Siegels richtet einen Feind und verursacht sofortigen Heiligschaden in Höhe von <!--ppl20375:20:28:46:280-->68 to <!--ppl20375:20:28:50:280:1-->73,oder <!--ppl20375:20:28:93:560-->137 to <!--ppl20375:20:28:101:560:1-->146 Heiligschaden,sollte das Ziel betäubt oder handlungsunfähig sein.');
