INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (721,'de','Heilige Nova');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (721,0,'de','Verursacht eine Explosion heiligen Lichts um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern <!--ppl15237:20:26:28:20-->29 to <!--ppl15237:20:26:32:20:1-->34 Heiligschaden zu. Zusätzlich werden alle Gruppenmitglieder in einem Umkreis von 10 Metern um <!--ppl15237:20:26:52:40-->54 to <!--ppl15237:20:26:60:40:1-->63 geheilt. Dieser Effekt erzeugt keine Bedrohung.');
