INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (723,'de','Geist der Erlösung');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (723,0,'de','Erhöht die gesamte Willenskraft um 5% und beim Tod verwandelt sich der Priester 15 sec lang in einen Geist der Erlösung. Der Geist kann sich weder bewegen oder angreifen,noch kann er das Ziel von Zaubern oder Effekten sein. In dieser Gestalt kann der Priester jeglichen Heilzauber ohne irgendwelche Kosten wirken. Nach Ablauf der Verwandlung stirbt der Priester.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (724,'de','Heilige Reichweite');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (724,0,'de','Erhöht die Reichweite Eurer Zauber ''Göttliche Pein'',''Heiliges Feuer'' sowie den Radius der Zauber ''Gebet der Heilung'',''Heilige Nova'' und ''Kreis der Heilung'' um 10%.');
