INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (726,'de','Brunnen des Lichts');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (726,0,'de','Erschafft einen heiligen Brunnen des Lichts. Mitglieder Eurer Gruppe oder Schlachtgruppe können den Brunnen des Lichts anklicken,um im Verlauf von 6 sec insgesamt 801 Gesundheit wiederherzustellen. Jeglicher erlittene Schaden bricht den Effekt ab. Der Brunnen des Lichts bleibt 3 min lang bestehen oder bis alle 5 Aufladungen verbraucht sind.');
