INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (728,0,'de','Bei Euren kritischen Treffern mit Zaubern besteht eine Chance von 25%,dass das nächste Wirken von ''Göttliche Pein'' sofort ist,kein Mana kostet,aber keine kritischen Treffer verursachen kann. Der Effekt hält 10 sec lang an.');
