INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (912,0,'de','Gewährt beiden,Hexenmeister und beschworenem Dämon,einen Effekt,solange dieser Dämon aktiv ist.<br /><br />Wichtel - Verringert die verursachte Bedrohung um 4%.<br /><br />Leerwandler - Verringert erlittenen körperlichen Schaden um 2%.<br /><br />Sukkubus/Inkubus - Erhöht jeglichen verursachten Schaden um 2%.<br /><br />Teufelsjäger - Erhöht alle Widerstände um 0,2 pro Stufe.<br /><br />Teufelswache: Erhöht jeglichen verursachten Schaden um 1% und alle Widerstände um 0,1 pro Stufe.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (912,1,'de','Gewährt beiden,Hexenmeister und beschworenem Dämon,einen Effekt,solange dieser Dämon aktiv ist.<br /><br />Wichtel - Verringert die verursachte Bedrohung um 8%.<br /><br />Leerwandler - Verringert erlittenen körperlichen Schaden um 4%.<br /><br />Sukkubus/Inkubus - Erhöht jeglichen verursachten Schaden um 4%.<br /><br />Teufelsjäger - Erhöht alle Widerstände um 0,4 pro Stufe.<br /><br />Teufelswache: Erhöht jeglichen verursachten Schaden um 2% und alle Widerstände um 0,2 pro Stufe.');
