INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (912,3,'de','Gewährt beiden,Hexenmeister und beschworenem Dämon,einen Effekt,solange dieser Dämon aktiv ist.<br /><br />Wichtel - Verringert die verursachte Bedrohung um 16%.<br /><br />Leerwandler - Verringert erlittenen körperlichen Schaden um 8%.<br /><br />Sukkubus/Inkubus - Erhöht jeglichen verursachten Schaden um 8%.<br /><br />Teufelsjäger - Erhöht alle Widerstände um 0,8 pro Stufe.<br /><br />Teufelswache: Erhöht jeglichen verursachten Schaden um 4% und alle Widerstände um 0,4 pro Stufe.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (912,4,'de','Gewährt beiden,Hexenmeister und beschworenem Dämon,einen Effekt,solange dieser Dämon aktiv ist.<br /><br />Wichtel - Verringert die verursachte Bedrohung um 20%.<br /><br />Leerwandler - Verringert erlittenen körperlichen Schaden um 10%.<br /><br />Sukkubus/Inkubus - Erhöht jeglichen verursachten Schaden um 10%.<br /><br />Teufelsjäger - Erhöht alle Widerstände um 1 pro Stufe.<br /><br />Teufelswache: Erhöht jeglichen verursachten Schaden um 5% und alle Widerstände um 0,5 pro Stufe.');
