INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1021,'de','Mondkingestalt');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1021,0,'de','Verwandelt Euch in die Mondkingestalt. Während Ihr Euch in dieser Gestalt befindet,wird der durch Gegenstände erzielte Rüstungswert um 370% erhöht,der erlittene Schaden während Betäubungseffekten um 15% verringert und die kritische Zaubertrefferchance aller Gruppenmitglieder im Umkreis von 100 Metern wird um 5% erhöht. Kritische Treffer mit Einzelzielzaubern stellen sofort 2% Eures gesamten Manas wieder her. In Mondkingestalt könnt Ihr weder Heil- noch Wiederbelebungszauber wirken.<br /><br />Der Akt des Gestaltwandelns befreit den Zaubernden von Verwandlungs- und bewegungseinschränkenden Effekten.');
