INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1030,0,'de','In Mondkingestalt haben gegen Euch geführte Angriffe eine Chance von 5%,Euch in Raserei zu versetzen,wodurch Euer verursachter Schaden um 10% erhöht wird,Ihr beim Wirken von Gleichgewichtszaubern durch erlittenen Schaden keine Verzögerung der Zauberzeit erleidet und alle 2 Sek. 2% Eures Grundmanas wiederhergestellt werden. Hält 10 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1030,1,'de','In Mondkingestalt haben gegen Euch geführte Angriffe eine Chance von 10%,Euch in Raserei zu versetzen,wodurch Euer verursachter Schaden um 10% erhöht wird,Ihr beim Wirken von Gleichgewichtszaubern durch erlittenen Schaden keine Verzögerung der Zauberzeit erleidet und alle 2 Sek. 2% Eures Grundmanas wiederhergestellt werden. Hält 10 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1030,2,'de','In Mondkingestalt haben gegen Euch geführte Angriffe eine Chance von 15%,Euch in Raserei zu versetzen,wodurch Euer verursachter Schaden um 10% erhöht wird,Ihr beim Wirken von Gleichgewichtszaubern durch erlittenen Schaden keine Verzögerung der Zauberzeit erleidet und alle 2 Sek. 2% Eures Grundmanas wiederhergestellt werden. Hält 10 sec lang an.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1031,'de','Taifun');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1031,0,'de','Ihr beschwört einen wilden Taifun,der an feindlichen Zielen bei Kontakt 400 Naturschaden verursacht,sie zurückstößt und 6 sec lang benommen macht.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1032,'de','Finsternis');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1032,0,'de','Erzielt Ihr mit ''Sternenfeuer'' einen kritischen Treffer,habt Ihr eine Chance von 33%,den verursachten Schaden Eures Zaubers ''Zorn'' um 40% zu erhöhen. Erzielt Ihr mit ''Zorn'' einen kritischen Treffer,habt Ihr eine Chance von 20%,die kritische Trefferchance Eures Zaubers ''Sternenfeuer'' um 40% zu erhöhen. Beide Effekte halten 15 sec lang an und haben eine separate Abklingzeit von 30 Sek. Die Effekte können nicht gleichzeitig auftreten.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1032,1,'de','Erzielt Ihr mit ''Sternenfeuer'' einen kritischen Treffer,habt Ihr eine Chance von 66%,den verursachten Schaden Eures Zaubers ''Zorn'' um 40% zu erhöhen. Erzielt Ihr mit ''Zorn'' einen kritischen Treffer,habt Ihr eine Chance von 40%,die kritische Trefferchance Eures Zaubers ''Sternenfeuer'' um 40% zu erhöhen. Beide Effekte halten 15 sec lang an und haben eine separate Abklingzeit von 30 Sek. Die Effekte können nicht gleichzeitig auftreten.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1032,2,'de','Erzielt Ihr mit ''Sternenfeuer'' einen kritischen Treffer,habt Ihr eine Chance von 100%,den verursachten Schaden Eures Zaubers ''Zorn'' um 40% zu erhöhen. Erzielt Ihr mit ''Zorn'' einen kritischen Treffer,habt Ihr eine Chance von 60%,die kritische Trefferchance Eures Zaubers ''Sternenfeuer'' um 40% zu erhöhen. Beide Effekte halten 15 sec lang an und haben eine separate Abklingzeit von 30 Sek. Die Effekte können nicht gleichzeitig auftreten.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1033,'de','Windböen');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1033,0,'de','Erhöht den Schaden Eurer Zauber ''Hurrikan'' und ''Taifun'' um 15% und die Reichweite Eures Zaubers ''Wirbelsturm'' um 2 Meter.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1033,1,'de','Erhöht den Schaden Eurer Zauber ''Hurrikan'' und ''Taifun'' um 30% und die Reichweite Eures Zaubers ''Wirbelsturm'' um 4 Meter.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1034,'de','Sternenregen');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1034,0,'de','Ihr beschwört einen Sternenschauer vom Himmel,der auf alle Ziele innerhalb von 30 Metern um den Zaubernden herniedergeht. Jeder Stern verursacht 145 to 167 Arkanschaden sowie an Gegnern innerhalb von 5 Metern um das feindliche Ziel zusätzliche 26 Arkanschaden. Es werden maximal 20 Sterne beschworen. Hält 10 sec lang an. Gestaltwandel in eine Tiergestalt oder Aufsitzen brechen den Effekt ab. Jedweder Effekt,der Euch die Kontrolle über Euren Charakter verlieren lässt,führt zum Abbruch von ''Sternenregen''.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1035,'de','Erde und Mond');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1035,0,'de','Eure Zauber ''Zorn'' und ''Sternenfeuer'' haben eine Chance von 100%,beim Ziel den Effekt ''Erde und Mond'' auszulösen. Dadurch wird der erlittene Zauberschaden des Ziels 12 sec lang um 4% erhöht. Erhöht auch Euren Zauberschaden um 2%.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1035,1,'de','Eure Zauber ''Zorn'' und ''Sternenfeuer'' haben eine Chance von 100%,beim Ziel den Effekt ''Erde und Mond'' auszulösen. Dadurch wird der erlittene Zauberschaden des Ziels 12 sec lang um 9% erhöht. Erhöht auch Euren verursachten Zauberschaden um 4%.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1035,2,'de','Eure Zauber ''Zorn'' und ''Sternenfeuer'' haben eine Chance von 100%,beim Ziel den Effekt ''Erde und Mond'' auszulösen. Dadurch wird der erlittene Zauberschaden des Ziels 12 sec lang um 13% erhöht. Erhöht auch Euren verursachten Zauberschaden um 6%.');
