INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1045,'de','Urfuror');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1045,0,'de','Verleiht Euch eine Chance von 50%,zusätzliche 5 Wut zu gewinnen,wenn Ihr in Bären- oder Terrorbärengestalt einen kritischen Treffer erzielt. Gewährt Euren kritischen Treffern aus Fähigkeiten,die Combopunkte erzeugen,eine Chance von 50%,dem Ziel einen zusätzlichen Combopunkt hinzuzufügen,wenn Ihr Euch in Katzengestalt befindet.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1045,1,'de','Verleiht Euch eine Chance von 100%,zusätzliche 5 Wut zu gewinnen,wenn Ihr in Bären- oder Terrorbärengestalt einen kritischen Treffer erzielt. Gewährt Euren kritischen Treffern aus Fähigkeiten,die Combopunkte erzeugen,eine Chance von 100%,dem Ziel einen zusätzlichen Combopunkt hinzuzufügen,wenn Ihr Euch in Katzengestalt befindet.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1046,'de','Schreddernde Angriffe');
