INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1046,1,'de','Verringert die Energiekosten Eurer Fähigkeit ''Schreddern'' um 18 und die Wutkosten Eurer Fähigkeit ''Aufschlitzen'' um 2.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1047,'de','Raubtierschläge');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1047,0,'de','Erhöht Eure Nahkampfangriffskraft in Katzen-,Bären- und Terrorbärengestalt um 50% Eurer aktuellen Stufe sowie um 7% der Angriffskraft Eurer ausgerüsteten Waffe. Zudem haben Eure Finishing-Moves eine Chance von 7% pro Combopunkt,Euren nächsten Naturzauber mit einer Zauberzeit von unter 10 Sek. zu einem Spontanzauber werden zu lassen.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1047,1,'de','Erhöht Eure Nahkampfangriffskraft in Katzen-,Bären- und Terrorbärengestalt um 100% Eurer aktuellen Stufe sowie um 14% der Angriffskraft Eurer ausgerüsteten Waffe. Zudem haben Eure Finishing-Moves eine Chance von 13% pro Combopunkt,Euren nächsten Naturzauber mit einer Zauberzeit von unter 10 Sek. zu einem Spontanzauber werden zu lassen.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1047,2,'de','Erhöht Eure Nahkampfangriffskraft in Katzen-,Bären- und Terrorbärengestalt um 150% Eurer aktuellen Stufe sowie um 20% der Angriffskraft Eurer ausgerüsteten Waffe. Zudem haben Eure Finishing-Moves eine Chance von 20% pro Combopunkt,Euren nächsten Naturzauber mit einer Zauberzeit von unter 10 Sek. zu einem Spontanzauber werden zu lassen.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1048,'de','Wilde Attacke');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1048,0,'de','Lehrt ''Wilde Attacke (Bär)'' und ''Wilde Attacke (Katze)''.<br /><br />Wilde Attacke (Bär) - Stürmt auf einen Gegner zu,macht ihn unbeweglich und unterbricht gewirkte Zauber. Hält 4 sec lang an. Die Fähigkeit kann in Bären- und Terrorbärengestalt genutzt werden. 15 Sekunden Abklingzeit.<br /><br />Wilde Attacke (Katze) - Springt hinter einen Gegner und macht ihn 3 sec lang benommen. 30 Sekunden Abklingzeit.');
