INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1059,1,'de','Durch Eure Fähigkeit ''Rudelführer'' heilen sich betroffene Ziele um 4% ihrer gesamten Gesundheit,wenn sie mit einem Nahkampf- oder Distanzangriff kritisch treffen. Dieser Heileffekt kann innerhalb von 6 Sek. nur einmal auftreten. Zusätzlich gewinnt Ihr 8% Eures gesamten Manas,wenn Ihr selbst von dieser Heilung profitiert.');
