INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1065,0,'de','Wenn aktiviert,gewährt Euch diese Fähigkeit,dass ''Zerfleischen (Bär)'' bis zu 3 Ziele trifft und keiner Abklingzeit unterliegt. In Katzengestalt werden die Energiekosten aller Eurer Fähigkeiten um 50% verringert. Hält 15 sec lang an. Während ''Berserker'' aktiv ist,kann ''Tigerfuror'' nicht genutzt werden.<br /><br />''Berserker'' entfernt sofort Furchteffekte und macht Euch während seiner Dauer gegen sie immun.');
