INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1066,0,'de','Erhöht in Bären- oder Terrorbärengestalt Eure Angriffskraft um 2% und verringert Euren erlittenen Schaden um 4%.');
