INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1086,'de','Vollkommenheit der Natur');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1086,0,'de','Eure kritische Zaubertrefferchance ist um 1% erhöht und kritische Treffer gegen Euch verleihen Euch den Effekt ''Vollkommenheit der Natur'',wodurch jeglicher erlittene Schaden um 2% verringert wird. Bis zu 3-mal stapelbar. Hält 8 sec lang an.');
