INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1087,'de','Baum des Lebens');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1087,0,'de','Verringert die Manakosten Eurer Zauber,die Heilung über Zeit hervorrufen,um 20% und verleiht Euch die Fähigkeit,Euch in den Baum des Lebens zu verwandeln. In dieser Gestalt erhöht Ihr die erhaltene Heilung aller Gruppen- und Schlachtzugsmitglieder im Umkreis von 100 Metern um 6%. Ihr könnt ausschließlich Wiederherstellungszauber,''Anregen'',''Baumrinde'',''Griff der Natur'' und ''Dornen'' wirken.<br /><br />Der Akt des Gestaltwandelns befreit den Zaubernden von Verwandlungs- und bewegungseinschränkenden Effekten.');
