INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1089,0,'de','Verleiht einen Effekt,der so lang aktiv ist,wie sich der Druide in der jeweiligen gestaltveränderten Form befindet.<br /><br />Bärengestalt - Erhöht körperlichen Schaden um 2%.<br /><br />Katzengestalt - Erhöht kritische Trefferchance um 2%.<br /><br />Mondkingestalt - Erhöht Zauberschaden um 2%.<br /><br />Baumgestalt - Erhöht Heilung um 2%.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1089,1,'de','Verleiht einen Effekt,der so lang aktiv ist,wie sich der Druide in der jeweiligen gestaltveränderten Form befindet.<br /><br />Bärengestalt - Erhöht körperlichen Schaden um 4%.<br /><br />Katzengestalt - Erhöht kritische Trefferchance um 4%.<br /><br />Mondkingestalt - Erhöht Zauberschaden um 4%.<br /><br />Baumgestalt - Erhöht Heilung um 4%.');
