INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1091,'de','Wildwuchs');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1091,0,'de','Heilt bis zu 5 verbündete Gruppen- oder Schlachtzugsmitglieder innerhalb von 15 Metern um das Ziel im Verlauf von 7 sec um [98 * 7 * (<!--sp57814:0-->(<!--sp57813:0-->(<!--sp57812:0-->(<!--sp57811:0--><!--sp57810:0-->1<!--sp57810--><!--sp57811-->)<!--sp57812-->)<!--sp57813-->)<!--sp57814-->)] Gesundheit. Die Heilung wird zunächst schnell und mit zunehmender Dauer von ''Wildwuchs'' langsamer angewendet.');
