INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1092,0,'de','Wenn Ihr mit Euren Zaubern ''Rasche Heilung'',''Nachwachsen'',''Pflege'' oder ''Heilende Berührung'' einen kritischen Treffer erzielt,habt Ihr eine Chance von 33%,dem Ziel für 30% des geheilten Wertes ein ''Samenkorn des Lebens'' einzupflanzen. Das Samenkorn wird erblühen,wenn das Ziel das nächste Mal angegriffen wird. Hält 15 sec lang an.');
