INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1150,1,'de','Sowohl Eure Frostfalle als auch Eure Schlangenfalle setzen bei ihrer Auslösung alle Ziele gefangen. Jedes der Ziele wird 3 sec lang bewegungsunfähig.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1150,2,'de','Sowohl Eure Frostfalle als auch Eure Schlangenfalle setzen bei ihrer Auslösung alle Ziele gefangen. Jedes der Ziele wird 4 sec lang bewegungsunfähig.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1151,'de','Fallenbeherrschung');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1151,0,'de','Frostfalle und Eiskältefalle - Erhöht die Dauer um 10%.<br /><br />Feuerbrandfalle,Sprengfalle und Schwarzer Pfeil - Erhöht den regelmäßigen Schaden um 10%.<br /><br />Schlangenfalle - Erhöht die Anzahl der beschworenen Schlangen um 2.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1151,1,'de','Frostfalle und Eiskältefalle - Erhöht die Dauer um 20%.<br /><br />Feuerbrandfalle,Sprengfalle und Schwarzer Pfeil - Erhöht den regelmäßigen Schaden um 20%.<br /><br />Schlangenfalle - Erhöht die Anzahl der beschworenen Schlangen um 4.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1151,2,'de','Frostfalle und Eiskältefalle - Erhöht die Dauer um 30%.<br /><br />Feuerbrandfalle,Sprengfalle und Schwarzer Pfeil - Erhöht den regelmäßigen Schaden um 30%.<br /><br />Schlangenfalle - Erhöht die Anzahl der beschworenen Schlangen um 6.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1152,'de','Sichern und Laden');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1152,0,'de','Wird ein Ziel durch Eure Eiskälte- oder Frostfalle oder Eure Fähigkeit ''Eiskältepfeil'' gefangen,besteht eine Chance von 33%; oder erleidet es durch den regelmäßigen Effekt Eurer Feuerbrandfalle,Sprengfalle oder Eurer Fähigkeit ''Schwarzer Pfeil'' Schaden,besteht eine Chance von 2%,dass Eure nächsten 2 Anwendungen von ''Arkaner Schuss'' oder ''Explosivschuss'' keine Abklingzeit auslösen,kein Mana kosten und keine Munition verbrauchen. Dieser Effekt hat eine Abklingzeit von 22 Sek.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1152,1,'de','Wird ein Ziel durch Eure Eiskälte- oder Frostfalle oder Eure Fähigkeit ''Eiskältepfeil'' gefangen,besteht eine Chance von 66%; oder erleidet es durch den regelmäßigen Effekt Eurer Feuerbrandfalle,Sprengfalle oder Eurer Fähigkeit ''Schwarzer Pfeil'' Schaden,besteht eine Chance von 4%,dass Eure nächsten 2 Anwendungen von ''Arkaner Schuss'' oder ''Explosivschuss'' keine Abklingzeit auslösen,kein Mana kosten und keine Munition verbrauchen. Dieser Effekt hat eine Abklingzeit von 22 Sek.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1152,2,'de','Wird ein Ziel durch Eure Eiskälte- oder Frostfalle oder Eure Fähigkeit ''Eiskältepfeil'' gefangen,besteht eine Chance von 100%; oder erleidet es durch den regelmäßigen Effekt Eurer Feuerbrandfalle,Sprengfalle oder Eurer Fähigkeit ''Schwarzer Pfeil'' Schaden,besteht eine Chance von 6%,dass Eure nächsten 2 Anwendungen von ''Arkaner Schuss'' oder ''Explosivschuss'' keine Abklingzeit auslösen,kein Mana kosten und keine Munition verbrauchen. Dieser Effekt hat eine Abklingzeit von 22 Sek.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1153,'de','Überlebenstaktik');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1153,0,'de','Verringert die Chance,dass Eurer Fähigkeit ''Totstellen'' und Euren Fallen widerstanden wird,um 2% und verringert die Abklingzeit von ''Rückzug'' um 2 Sek.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1153,1,'de','Verringert die Chance,dass Eurer Fähigkeit ''Totstellen'' und Euren Fallen widerstanden wird,um 4% und verringert die Abklingzeit von ''Rückzug'' um 4 Sek.');
