INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1168,0,'de','Ein einzelner Kurzdistanzschuss,der 50% Waffenschaden zufügt und das Ziel 4 sec lang die Orientierung verlieren lässt. Jeglicher erlittene Schaden wird den Effekt aufheben. Stoppt Euren Angriff bei Benutzung.');
