INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1170,0,'de','Wird ''Stich des Flügeldrachen'' gebannt,wird der Bannende ebenfalls für 16% der verbliebenen Dauer von ''Stich des Flügeldrachen'' betroffen. Erhöht zudem jeglichen Schaden um 1%,den Ihr an Zielen verursacht,die von Eurem ''Schlangenbiss'' betroffen sind.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1170,1,'de','Wird ''Stich des Flügeldrachen'' gebannt,wird der Bannende ebenfalls für 25% der verbliebenen Dauer von ''Stich des Flügeldrachen'' betroffen. Erhöht zudem jeglichen Schaden um 2%,den Ihr an Zielen verursacht,die von Eurem ''Schlangenbiss'' betroffen sind.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1170,2,'de','Wird ''Stich des Flügeldrachen'' gebannt,wird der Bannende ebenfalls für 50% der verbliebenen Dauer von ''Stich des Flügeldrachen'' betroffen. Erhöht zudem jeglichen Schaden um 3%,den Ihr an Zielen verursacht,die von Eurem ''Schlangenbiss'' betroffen sind.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1171,'de','Kein Entkommen');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1171,0,'de','Erhöht die kritische Trefferchance aller Eurer Angriffe gegen alle Ziele,die von Euren Fähigkeiten ''Frostfalle'',''Eiskältefalle'' und ''Eiskältepfeil'' betroffen sind,um 3%.');
