INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1172,0,'de','Erhöht die kritische Trefferchance Eurer Fähigkeit ''Tödlicher Schuss'' um 5%. Wenn Ihr 6 Sek. lang stillsteht,erhöht das Scharfschützentraining den verursachten Schaden Eurer Fähigkeiten ''Zuverlässiger Schuss'',''Gezielter Schuss'',''Schwarzer Pfeil'' und ''Explosivschuss'' um 2%. Hält 15 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1172,1,'de','Erhöht die kritische Trefferchance Eurer Fähigkeit ''Tödlicher Schuss'' um 10%. Wenn Ihr 6 Sek. lang stillsteht,erhöht das Scharfschützentraining den verursachten Schaden Eurer Fähigkeiten ''Zuverlässiger Schuss'',''Gezielter Schuss'',''Schwarzer Pfeil'' und ''Explosivschuss'' um 4%. Hält 15 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1172,2,'de','Erhöht die kritische Trefferchance Eurer Fähigkeit ''Tödlicher Schuss'' um 15%. Wenn Ihr 6 Sek. lang stillsteht,erhöht das Scharfschützentraining den verursachten Schaden Eurer Fähigkeiten ''Zuverlässiger Schuss'',''Gezielter Schuss'',''Schwarzer Pfeil'' und ''Explosivschuss'' um 6%. Hält 15 sec lang an.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1173,'de','Jagdgesellschaft');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1173,0,'de','Erhöht Eure gesamte Beweglichkeit um zusätzliche 1%. Die kritischen Treffer Eurer Fähigkeiten ''Arkaner Schuss'',''Explosivschuss'' und ''Zuverlässiger Schuss'' haben eine Chance von 33%,bei bis zu 10 Gruppen- oder Schlachtzugsmitgliedern alle 5 Sek. 1% ihres maximalen Manas wiederherzustellen. Hält 15 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1173,1,'de','Erhöht Eure gesamte Beweglichkeit um zusätzliche 2%. Die kritischen Treffer Eurer Fähigkeiten ''Arkaner Schuss'',''Explosivschuss'' und ''Zuverlässiger Schuss'' haben eine Chance von 66%,bei bis zu 10 Gruppen- oder Schlachtzugsmitgliedern alle 5 Sek. 1% ihres maximalen Manas wiederherzustellen. Hält 15 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1173,2,'de','Erhöht Eure gesamte Beweglichkeit um zusätzliche 3%. Die kritischen Treffer Eurer Fähigkeiten ''Arkaner Schuss'',''Explosivschuss'' und ''Zuverlässiger Schuss'' haben eine Chance von 100%,bei bis zu 10 Gruppen- oder Schlachtzugsmitgliedern alle 5 Sek. 1% ihres maximalen Manas wiederherzustellen. Hält 15 sec lang an.');
