INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1228,0,'de','Zielen in einem kegelförmigen Bereich vor dem Zaubernden wird <!--ppl31661:50:58:370:150-->382 to <!--ppl31661:50:58:430:150:1-->442 Feuerschaden zugefügt und sie werden 5 sec lang desorientiert und verlangsamt. Jeder Angriff,der direkten Schaden verursacht,lässt das Ziel wieder zu sich kommen. Stoppt Euren Angriff bei Benutzung.');
