INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1295,0,'de','Erhöht die Blockchance 10 sec lang um 30% und verursacht,solang aktiv,mit jedem geblockten Angriff 79 Heiligschaden. Jedes Blocken verbraucht eine der 8 Aufladungen.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1296,'de','Segen des Refugiums');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1296,0,'de','Belegt ein befreundetes Ziel mit einem Segen,der jeglichen erlittenen Schaden des Ziels 10 min lang um bis zu 3% verringert sowie die Ausdauer und Stärke um 10% erhöht. Zusätzlich gewinnt das Ziel durch Nahkampfangriffe,die es blockt,pariert,oder denen es ausweicht,2% des angezeigten maximalen Manas. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein.');
