INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1302,0,'de','Erhöht Eure gesamte Ausdauer um 2% und verringert die Abklingzeit Eurer Zauber ''Gottesschild'' und ''Göttlicher Schutz'' um 30 Sek.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1302,1,'de','Erhöht Eure gesamte Ausdauer um 4% und verringert die Abklingzeit Eurer Zauber ''Gottesschild'' und ''Göttlicher Schutz'' um 60 Sek.');
