INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1303,1,'de','Erlittener Schaden,der Eure Gesundheit unter 35% senkt,wird um 13% verringert. Zusätzlich werdet Ihr durch Angriffe,die Euch normalerweise töten würden,um bis zu 20% Eurer maximalen Gesundheit geheilt (der geheilte Wert basiert auf Verteidigung). Dieser Effekt kann nur ein Mal alle 2 min auftreten.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1303,2,'de','Erlittener Schaden,der Eure Gesundheit unter 35% senkt,wird um 20% verringert. Zusätzlich werdet Ihr durch Angriffe,die Euch normalerweise töten würden,um bis zu 30% Eurer maximalen Gesundheit geheilt (der geheilte Wert basiert auf Verteidigung). Dieser Effekt kann nur ein Mal alle 2 min auftreten.');
