INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1307,1,'de','Verringert den erlittenen Zauberschaden um 6% und gewährt eine Chance von 100%,dass die Dauer von ''Göttliche Bitte'' aufgefrischt wird,wenn Ihr einen Feind schlagt. Zusätzlich wird die Chance,dass ''Göttliche Bitte'' gebannt wird,um 100% verringert.');
