INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1312,'de','Heilige Opferung');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1312,0,'de','30% jeglichen von Gruppenmitgliedern im Umkreis von 30 Metern erlittenen Schadens wird auf den Paladin umgelenkt (bis zu einem Maximum von 40% der Gesundheit des Paladins multipliziert mit der Anzahl der Gruppenmitglieder). Schaden,der die Gesundheit des Paladins auf unter 20% senkt,wird den Effekt abbrechen. Hält 10 sec lang an.');
