INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1313,0,'de','Ist Euer Zauber ''Heilige Opferung'' aktiviert,wird der erlittene Schaden von Gruppen- und Schlachtzugsmitgliedern innerhalb von 30 Metern 6 sec lang um 10% verringert. Zudem wird die Dauer Eures Zaubers ''Geheiligter Schild'' um 50% und der absorbierte Betrag um 10% erhöht.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1313,1,'de','Ist Euer Zauber ''Heilige Opferung'' aktiviert,wird der erlittene Schaden von Gruppen- und Schlachtzugsmitgliedern innerhalb von 30 Metern 6 sec lang um 20% verringert. Zudem wird die Dauer Eures Zaubers ''Geheiligter Schild'' um 100% und der absorbierte Betrag um 20% erhöht.');
