INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1323,'de','Siegel des Befehls');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1323,0,'de','Alle Nahkampfangriffe verursachen (0.36 * Mainhand weapon min damage) bis (0.36 * Mainhand weapon max damage) zusätzlichen Heiligschaden. Wird dieser Zauber mit Angriffen oder Fähigkeiten genutzt,die ein einzelnes Ziel treffen,trifft der zusätzliche Heiligschaden bis zu 2 zusätzliche Ziele. Hält 30 min lang an.<br /><br />Die Entfesselung der Energie dieses Siegels richtet einen Feind und verursacht sofort (0.19 * Mainhand weapon min damage + 0.08 * Attack power + 0.13 * Spell power) bis (0.19 * Mainhand weapon max damage + 0.08 * Attack power + 0.13 * Spell power) Heiligschaden.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1324,'de','Verbesserte Richturteile');
