INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1325,'de','Auge um Auge');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1325,0,'de','Ein Angreifer erleidet durch kritische Treffer gegen Euch 5% seines verursachten Schadens. Der von ''Auge um Auge'' verursachte Schaden kann nie 50% der gesamten Gesundheit des Paladins überschreiten.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1325,1,'de','Ein Angreifer erleidet durch kritische Treffer gegen Euch 10% seines verursachten Schadens. Der von ''Auge um Auge'' verursachte Schaden kann nie 50% der gesamten Gesundheit des Paladins überschreiten.');
