INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1326,0,'de','Gewährt den Schaden verursachenden Angriffen des Paladins eine Chance,die Angriffskraft des Ziels 10 sec lang um <!--ppl9452:20:80:23:440:1-->287 zu verringern.');
