INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1327,0,'de','Verringert die Dauer aller Entwaffnungseffekte um 25% und erhöht Euer normales Bewegungstempo und Euer Bewegungstempo beim Reiten um 8%. Ergänzt sich nicht mit anderen Effekten,die das Bewegungstempo erhöhen.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1327,1,'de','Verringert die Dauer aller Entwaffnungseffekte um 50% und erhöht Euer normales Bewegungstempo und Euer Bewegungstempo beim Reiten um 15%. Ergänzt sich nicht mit anderen Effekten,die das Bewegungstempo erhöhen.');
