INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1328,0,'de','Erhöht jeglichen verursachten Schaden um 1% und den Schaden an Humanoiden,Dämonen,Untoten und Elementaren zusätzlich um 1%.');
