INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1330,0,'de','Verringert Eure Chance,von Zaubern und Distanzangriffen getroffen zu werden,um 2% und verleiht Eurem Zauber ''Hand der Freiheit'' eine Chance von 50%,einen Betäubungseffekt vom Ziel zu entfernen.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1330,1,'de','Verringert Eure Chance,von Zaubern und Distanzangriffen getroffen zu werden,um 4% und verleiht Eurem Zauber ''Hand der Freiheit'' eine Chance von 100%,einen Betäubungseffekt vom Ziel zu entfernen.');
