INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1331,1,'de','Eure Schaden verursachenden Richturteilszauber haben eine Chance von 66%,bis zu 10 Gruppen- oder Schlachtzugsmitgliedern 15 sec lang den Effekt ''Erfrischung'' zu gewähren,der alle 5 Sek. 1% ihres maximalen Manas wiederherstellt und Euch sofort 25% Eures Grundmanas gewährt.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1331,2,'de','Eure Schaden verursachenden Richturteilszauber haben eine Chance von 100%,bis zu 10 Gruppen- oder Schlachtzugsmitgliedern 15 sec lang den Effekt ''Erfrischung'' zu gewähren,der alle 5 Sek. 1% ihres maximalen Manas wiederherstellt und Euch sofort 25% Eures Grundmanas gewährt.');
