INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1339,1,'de','Erhöht sowohl den Schaden Eurer Richturteilszauber,als auch den Eurer Zauber ''Kreuzfahrerstoß'' und ''Göttlicher Sturm'' um 10%. Zudem wird,wenn Eure Nahkampfangriffe kritisch treffen,Euer nächstes Wirken von ''Lichtblitz'' oder ''Exorzismus'' zu einem Spontanzauber.');
