INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1341,0,'de','Gewährt Euch eine Chance von 50%,den Effekt ''Fokussiertes Zauberwirken'' zu erhalten,der 6 sec lang anhält,nachdem Ihr Opfer eines kritischen Nahkampf- oder Distanzangriffs wart. Der Effekt ''Fokussiertes Zauberwirken'' verringert die Dauer der durch erlittenen Schaden verursachten Zauberzeiterhöhung beim Wirken von Priesterzaubern und die Dauer von Unterbrechungseffekten um 10%.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1341,1,'de','Gewährt Euch eine Chance von 100%,den Effekt ''Fokussiertes Zauberwirken'' zu erhalten,der 6 sec lang anhält,nachdem Ihr Opfer eines kritischen Nahkampf- oder Distanzangriffs wart. Der Effekt ''Fokussiertes Zauberwirken'' verringert die Dauer der durch erlittenen Schaden verursachten Zauberzeiterhöhung beim Wirken von Priesterzaubern und die Dauer von Unterbrechungseffekten um 20%.');
