INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1359,'de','Schmerzunterdrückung');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1359,0,'de','Verringert die Bedrohung eines befreundeten Ziels sofort um 5%,8 sec lang wird jeglicher erlittene Schaden um 40% verringert und die Chance,Bannzaubern zu widerstehen,um 65% erhöht.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1360,'de','Fokussierter Wille');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1360,0,'de','Erhöht die Chance auf kritische Effekte Eurer Zauber um 1%. Nach einem erlittenen kritischen Treffer wird Euch der Effekt ''Fokussierter Wille'' gewährt,wodurch jeglicher erlittene Schaden um 2% verringert und erhaltene Heileffekte um 3% erhöht werden. Bis zu 3-mal stapelbar. Hält 8 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1360,1,'de','Erhöht die Chance auf kritische Effekte Eurer Zauber um 2%. Nach einem erlittenen kritischen Treffer wird Euch der Effekt ''Fokussierter Wille'' gewährt,wodurch jeglicher erlittene Schaden um 3% verringert und erhaltene Heileffekte um 4% erhöht werden. Bis zu 3-mal stapelbar. Hält 8 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1360,2,'de','Erhöht die Chance auf kritische Effekte Eurer Zauber um 3%. Nach einem erlittenen kritischen Treffer wird Euch der Effekt ''Fokussierter Wille'' gewährt,wodurch jeglicher erlittene Schaden um 4% verringert und erhaltene Heileffekte um 5% erhöht werden. Bis zu 3-mal stapelbar. Hält 8 sec lang an.');
