INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1362,1,'de','Kritische Heilungen hüllen das Ziel in einen schützenden Schild,der Schaden in Höhe von 20% des geheilten Wertes absorbiert. Hält 12 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1362,2,'de','Kritische Heilungen hüllen das Ziel in einen schützenden Schild,der Schaden in Höhe von 30% des geheilten Wertes absorbiert. Hält 12 sec lang an.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1363,'de','Euphorie');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1363,0,'de','Wenn der Effekt Eures Zaubers ''Machtwort: Schild'' gebannt oder durch absorbierten Schaden beendet wird,gewinnt Ihr sofort 1,5% Eures maximalen Manas. Es besteht eine Chance von 33%,dass ein schildgeschütztes Ziel 2% seines gesamten Manas,8 Wut,16 Energie oder 32 Runenmacht gewinnt. Dieser Effekt kann nur ein Mal alle 12 sec auftreten.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1363,1,'de','Wenn der Effekt Eures Zaubers ''Machtwort: Schild'' gebannt oder durch absorbierten Schaden beendet wird,gewinnt Ihr sofort 2% Eures maximalen Manas. Es besteht eine Chance von 66%,dass ein schildgeschütztes Ziel 2% seines gesamten Manas,8 Wut,16 Energie oder 32 Runenmacht gewinnt. Dieser Effekt kann nur ein Mal alle 12 sec auftreten.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1363,2,'de','Wenn der Effekt Eures Zaubers ''Machtwort: Schild'' gebannt oder durch absorbierten Schaden beendet wird,gewinnt Ihr sofort 2,5% Eures maximalen Manas. Es besteht eine Chance von 100%,dass ein schildgeschütztes Ziel 2% seines gesamten Manas,8 Wut,16 Energie oder 32 Runenmacht gewinnt. Dieser Effekt kann nur ein Mal alle 12 sec auftreten.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1364,'de','Sühne');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1364,0,'de','Schleudert eine Salve heiligen Lichts auf das Ziel,die an einem Feind 240 Heiligschaden verursacht oder ein freundliches Ziel sofort um 670 to 756 heilt sowie 2 sec lang alle 1 Sek.');
