INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1366,'de','Barmherzigkeit');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1366,0,'de','Eure Zauber ''Blitzheilung'',''Große Heilung'' und ''Sühne'' haben eine Chance von 50%,das Ziel mit Barmherzigkeit zu segnen,die seine durch den Priester erhaltene Heilung um 3% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar und hält 15 sec lang an. ''Barmherzigkeit'' kann jeweils nur auf ein Ziel wirken.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1366,1,'de','Eure Zauber ''Blitzheilung'',''Große Heilung'' und ''Sühne'' haben eine Chance von 100%,das Ziel mit Barmherzigkeit zu segnen,die seine durch den Priester erhaltene Heilung um 3% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar und hält 15 sec lang an. ''Barmherzigkeit'' kann jeweils nur auf ein Ziel wirken.');
