INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1367,0,'de','Erhöht die Chance auf kritische Effekte Eurer Zauber ''Blitzheilung'',''Große Heilung'' und ''Sühne'' (Heilung) um 2%,wenn das Ziel von ''Geschwächte Seele'' betroffen ist. Zudem besteht beim Wirken von ''Machtwort: Schild'' eine Chance von 50%,jeglichen erlittenen Schaden aller Gruppen- und Schlachtzugsmitglieder 1 min lang um 3% zu verringern. Dieser Effekt hat eine Abklingzeit von 2 Sek.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1367,1,'de','Erhöht die Chance auf kritische Effekte Eurer Zauber ''Blitzheilung'',''Große Heilung'' und ''Sühne'' (Heilung) um 4%,wenn das Ziel von ''Geschwächte Seele'' betroffen ist. Zudem besteht beim Wirken von ''Machtwort: Schild'' eine Chance von 100%,jeglichen erlittenen Schaden aller Gruppen- und Schlachtzugsmitglieder 1 min lang um 3% zu verringern. Dieser Effekt hat eine Abklingzeit von 2 Sek.');
