INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1383,0,'de','Heilt Euch nach dem Erleiden eines kritischen Nahkampf- oder Distanzangrifftreffers im Verlauf von 6 sec um 5% des zugefügten Schadens. Zusätzlich während dieser Dauer erlittene kritische Treffer erhöhen die erhaltene Heilung.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1383,1,'de','Heilt Euch nach dem Erleiden eines kritischen Nahkampf- oder Distanzangrifftreffers im Verlauf von 6 sec um 10% des zugefügten Schadens. Zusätzlich während dieser Dauer erlittene kritische Treffer erhöhen die erhaltene Heilung.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1383,2,'de','Heilt Euch nach dem Erleiden eines kritischen Nahkampf- oder Distanzangrifftreffers im Verlauf von 6 sec um 15% des zugefügten Schadens. Zusätzlich während dieser Dauer erlittene kritische Treffer erhöhen die erhaltene Heilung.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1384,'de','Brunnen des Lichts');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1384,0,'de','Erschafft einen heiligen Brunnen des Lichts. Befreundete Spieler können den Brunnen des Lichts anklicken,um im Verlauf von 6 sec insgesamt <!--sp55673:0-->801<!--sp55673--> Gesundheit wiederherzustellen. Erlittener Schaden,der 30% Eurer gesamten Gesundheit entspricht,bricht den Effekt ab. Der Brunnen des Lichts bleibt 3 min lang bestehen oder bis 10 Aufladungen verbraucht sind.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1385,'de','Gesegnete Abhärtung');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1385,0,'de','Erhöht die Effektivität Eurer Heilzauber um 1%. Erleidet Ihr einen kritischen Treffer,besteht eine Chance von 20%,dass 6 sec lang weitere kritische Treffer gegen Euch verhindert werden.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1385,1,'de','Erhöht die Effektivität Eurer Heilzauber um 2%. Erleidet Ihr einen kritischen Treffer,besteht eine Chance von 40%,dass 6 sec lang weitere kritische Treffer gegen Euch verhindert werden.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1385,2,'de','Erhöht die Effektivität Eurer Heilzauber um 3%. Erleidet Ihr einen kritischen Treffer,besteht eine Chance von 60%,dass 6 sec lang weitere kritische Treffer gegen Euch verhindert werden.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1386,'de','Woge des Lichts');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1386,0,'de','Eure kritischen Zaubertreffer haben eine Chance von 25%,dass das nächste Wirken von ''Göttliche Pein'' oder ''Blitzheilung'' ein Spontanzauber ist und kein Mana kostet,aber keinen kritischen Treffer erzielen kann. Der Effekt hält 10 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1386,1,'de','Eure kritischen Zaubertreffer haben eine Chance von 50%,dass das nächste Wirken von ''Göttliche Pein'' oder ''Blitzheilung'' ein Spontanzauber ist und kein Mana kostet,aber keinen kritischen Treffer erzielen kann. Der Effekt hält 10 sec lang an.');
