INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1388,0,'de','Erzielt Ihr mit ''Blitzheilung'',''Große Heilung'',''Verbindende Heilung'' oder ''Machterfüllte Erneuerung'' einen kritischen Effekt,wird die Manaregeneration durch Eure Willenskraft 8 sec lang um 16% erhöht.');
