INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1392,0,'de','Wenn Ihr ''Verbindende Heilung'' oder ''Blitzheilung'' wirkt,wird die Zauberzeit Eures nächsten Wirkens von ''Große Heilung'' oder ''Gebet der Heilung'' um 4% verringert. Bis zu 3-mal stapelbar. Hält 20 sec lang an.');
