INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1394,'de','Schutzgeist');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1394,0,'de','Ruft einen Schutzgeist herbei,der ein freundliches Ziel bewacht. Der Geist erhöht die erhaltene Heilung des Ziels um 40% und verhindert,dass das Ziel stirbt,indem er sich selbst opfert. Dieses Opfer beendet den Effekt,heilt das Ziel jedoch um 50% seiner maximalen Gesundheit. Hält 10 sec lang an.');
