INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1395,0,'de','Wenn Ihr ''Machtwort: Schild'' wirkt,wird das Bewegungstempo des Ziels 4 sec lang um 30% erhöht. Zudem besteht eine Chance von 50%,dass Ihr beim Wirken von ''Krankheit aufheben'' auf Euch selbst,zusätzlich zu den Krankheiten einen Gifteffekt entfernt.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1395,1,'de','Wenn Ihr ''Machtwort: Schild'' wirkt,wird das Bewegungstempo des Ziels 4 sec lang um 60% erhöht. Zudem besteht eine Chance von 100%,dass Ihr beim Wirken von ''Krankheit aufheben'' auf Euch selbst,zusätzlich zu den Krankheiten einen Gifteffekt entfernt.');
