INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1401,1,'de','Verringert die Abklingzeit Eures Zaubers ''Gedankenschlag'' um 1 Sek. Zudem hat in Schattengestalt Euer Zauber ''Gedankenschlag'' eine Chance von 40%,die erhaltene Heilung des Ziels 10 sec lang um 20% zu verringern.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1401,2,'de','Verringert die Abklingzeit Eures Zaubers ''Gedankenschlag'' um 1.5 Sek. Zudem hat in Schattengestalt Euer Zauber ''Gedankenschlag'' eine Chance von 60%,die erhaltene Heilung des Ziels 10 sec lang um 20% zu verringern.');
