INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1403,1,'de','Verringert die Abklingzeit Eurer Fähigkeit ''Verblassen'' um 6 Sek. und verringert die Abklingzeit Eures Schattengeistes um 2 Min.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1404,'de','Vampirumarmung');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1404,0,'de','Die Umarmung der Schattenenergie umschlingt Euch,wodurch Ihr Euch um 15% und andere Gruppenmitglieder um 3% des von Euch auf ein einzelnes Ziel verursachten Schattenschadens heilt. Hält 30 min lang an.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1405,'de','Gedankenschinden');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1405,0,'de','Greift die Gedanken des Ziels mit Schattenenergie an,verursacht im Verlauf von 3 sec 45 Schattenschaden und verringert das Bewegungstempo des Ziels um 50%.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1406,'de','Schattengestalt');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1406,0,'de','Ihr nehmt eine Schattengestalt an,erhöht Euren Schattenschaden um 15% und verringert den von Euch erlittenen Schaden um 15% sowie Eure erzeugte Bedrohung um 30%. Ihr könnt in dieser Gestalt außer ''Krankheit heilen'' und ''Krankheit aufheben'' jedoch keine Heiligzauber wirken. Gewährt dem regelmäßigen Schaden Eurer Zauber ''Schattenwort: Schmerz'',''Verschlingende Seuche'' und ''Vampirberührung'' für um 100% erhöhten Schaden kritisch zu treffen sowie ''Verschlingende Seuche'' und ''Vampirberührung'' die Fähigkeit,von Tempo zu profitieren.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1407,'de','Stille');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1407,0,'de','Bringt das Ziel zum Schweigen,sodass es 5 sec lang keine Zauber wirken kann. Das Zauberwirken von Nichtspieler-Zielen ist ebenfalls 3 sec lang unterbrochen.');
