INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1413,'de','Vampirberührung');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1413,0,'de','Fügt dem Ziel im Verlauf von 15 sec insgesamt 450 Schattenschaden zu und gewährt bis zu 10 Gruppen- oder Schlachtzugsmitgliedern alle 5 Sek. 1% ihres maximalen Manas,wenn Ihr durch ''Gedankenschlag'' Schaden verursacht. Zusätzlich erleidet das von ''Vampirberührung'' betroffene Ziel 720 Schaden,wenn der Effekt gebannt wird.');
