INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1414,0,'de','Erhöht die kritische Trefferchance Eurer Zauber ''Gedankenschlag'',''Gedankenschinden'' und ''Gedankenexplosion'' um 2%. Erhöht zudem die regelmäßige kritische Trefferchance Eurer Zauber ''Vampirberührung'',''Verschlingende Seuche'' und ''Schattenwort: Schmerz'' um 3%.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1414,1,'de','Erhöht die kritische Trefferchance Eurer Zauber ''Gedankenschlag'',''Gedankenschinden'' und ''Gedankenexplosion'' um 4%. Erhöht zudem die regelmäßige kritische Trefferchance Eurer Zauber ''Vampirberührung'',''Verschlingende Seuche'' und ''Schattenwort: Schmerz'' um 6%.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1415,'de','Elend');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1415,0,'de','Eure Zauber ''Schattenwort: Schmerz'',''Gedankenschinden'' und ''Vampirberührung'' erhöhen 24 sec lang zusätzlich die Trefferchance von Schadenszaubern um 1%. Erhöht zudem den Bonus,den Eure Zauber ''Gedankenschlag'',''Gedankenschinden'' und ''Gedankenexplosion'' durch Zaubermacht erhalten,um 5%.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1415,1,'de','Eure Zauber ''Schattenwort: Schmerz'',''Gedankenschinden'' und ''Vampirberührung'' erhöhen 24 sec lang zusätzlich die Trefferchance von Schadenszaubern um 2%. Erhöht zudem den Bonus,den Eure Zauber ''Gedankenschlag'',''Gedankenschinden'' und ''Gedankenexplosion'' durch Zaubermacht erhalten,um 10%.');
