INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1416,'de','Verbesserte Schattengestalt');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1416,0,'de','Eure Fähigkeit ''Verblassen'' hat in Schattengestalt nun eine Chance von 50%,jegliche bewegungseinschränkende Effekte zu entfernen und die erhöhte Zauberdauer und verringerte Kanalisierungsdauer durch erlittenen Schaden wird um 35% verringert,wenn Ihr in Schattengestalt Schattenzauber wirkt.');
