INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1420,'de','Dispersion');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1420,0,'de','Löst Euch zu reiner Schattenenergie auf und verringert jeglichen erlittenen Schaden um 90%. Ihr könnt weder angreifen noch Zauber wirken,regeneriert jedoch 6 sec lang alle 1 Sek. 6% Mana. ''Dispersion'' kann gewirkt werden,während Betäubungs-,Furcht- oder Stilleeffekte auf Euch wirken. Bei Anwendung werden alle wirkenden Verlangsamungs- und bewegungseinschränkenden Effekte entfernt und Ihr werdet für die Dauer des Effektes von ''Dispersion'' gegen sie immun.');
