INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1421,0,'de','Die kritischen Treffer Eurer Zauber ''Gedankenschlag'' und ''Schattenwort: Tod'' haben eine Chance von 100% und die kritischen Treffer Eures Zaubers ''Gedankenschinden'' eine Chance von 50%,Eure gesamte Willenskraft um 5% zu erhöhen. Während der Effekt andauert,wird Eure Manaregeneration während des Zauberwirkens auf 17% erhöht. Hält 8 sec lang an.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1421,1,'de','Die kritischen Treffer Eurer Zauber ''Gedankenschlag'' und ''Schattenwort: Tod'' haben eine Chance von 100% und die kritischen Treffer Eures Zaubers ''Gedankenschinden'' eine Chance von 50%,Eure gesamte Willenskraft um 10% zu erhöhen. Während der Effekt andauert,wird Eure Manaregeneration während des Zauberwirkens auf 33% erhöht. Hält 8 sec lang an.');
