INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1562,0,'de','Wenn Ihr mit ''Welle der Heilung'' oder ''Springflut'' einen kritischen Effekt erzielt,besteht eine Chance von 33%,dass Ihr sofort Mana gewinnt,als wäre eine Kugel des Wasserschilds verbraucht worden. Wenn Ihr mit ''Geringe Welle der Heilung'' einen kritischen Effekt erzielt,liegt die Chance,diesen Effekt auszulösen,bei 20% und bei 10%,wenn Ihr mit ''Kettenheilung'' einen kritischen Effekt erzielt.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1562,1,'de','Wenn Ihr mit ''Welle der Heilung'' oder ''Springflut'' einen kritischen Effekt erzielt,besteht eine Chance von 66%,dass Ihr sofort Mana gewinnt,als wäre eine Kugel des Wasserschilds verbraucht worden. Wenn Ihr mit ''Geringe Welle der Heilung'' einen kritischen Effekt erzielt,liegt die Chance,diesen Effekt auszulösen,bei 40% und bei 20%,wenn Ihr mit ''Kettenheilung'' einen kritischen Effekt erzielt.');
