INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1578,0,'de','Schützt das Ziel mit einem Erdschild,der die erhöhte Zauberdauer oder verringerte Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um <!--sp63279:0-->150<!--sp63279--> heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 6 Aufladungen. Hält 10 min lang an. Der Erdschild kann immer nur auf einem Ziel gleichzeitig aktiv sein,und auf jedem Ziel kann nur ein Elementarschild aktiv sein.');
