INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1583,'de','Flutwellen');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1583,0,'de','Beim Wirken von ''Kettenheilung'' oder ''Springflut'' besteht eine Chance von 20%,dass die Zauberzeit von ''Welle der Heilung'' um 30% verringert und die Chance auf einen kritischen Effekt von ''Geringe Welle der Heilung'' um 25% erhöht wird. Bleibt aktiv,bis zwei Zauber dieser Art gewirkt wurden. Zusätzlich werden die Bonusheilungseffekte von ''Welle der Heilung'' um 4% und von ''Geringe Welle der Heilung'' um 2% erhöht.');
