INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1583,2,'de','Beim Wirken von ''Kettenheilung'' oder ''Springflut'' besteht eine Chance von 60%,dass die Zauberzeit von ''Welle der Heilung'' um 30% verringert und die Chance auf einen kritischen Effekt von ''Geringe Welle der Heilung'' um 25% erhöht wird. Bleibt aktiv,bis zwei Zauber dieser Art gewirkt wurden. Zusätzlich werden die Bonusheilungseffekte von ''Welle der Heilung'' um 12% und von ''Geringe Welle der Heilung'' um 6% erhöht.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1583,3,'de','Beim Wirken von ''Kettenheilung'' oder ''Springflut'' besteht eine Chance von 80%,dass die Zauberzeit von ''Welle der Heilung'' um 30% verringert und die Chance auf einen kritischen Effekt von ''Geringe Welle der Heilung'' um 25% erhöht wird. Bleibt aktiv,bis zwei Zauber dieser Art gewirkt wurden. Zusätzlich werden die Bonusheilungseffekte von ''Welle der Heilung'' um 16% und von ''Geringe Welle der Heilung'' um 8% erhöht.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1583,4,'de','Beim Wirken von ''Kettenheilung'' oder ''Springflut'' besteht eine Chance von 100%,dass die Zauberzeit von ''Welle der Heilung'' um 30% verringert und die Chance auf einen kritischen Effekt von ''Geringe Welle der Heilung'' um 25% erhöht wird. Bleibt aktiv,bis zwei Zauber dieser Art gewirkt wurden. Zusätzlich werden die Bonusheilungseffekte von ''Welle der Heilung'' um 20% und von ''Geringe Welle der Heilung'' um 10% erhöht.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1584,'de','Springflut');
