INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1604,0,'de','Schattenenergie zerstört langsam das Ziel,im Verlauf von 15 sec wird insgesamt 550 Schaden verursacht. Sollte ''Instabiles Gebrechen'' gebannt werden,erleidet der Bannende 990 Schaden und wird 5 sec lang zum Schweigen gebracht. Es kann pro Hexenmeister jeweils nur ein Effekt von ''Feuerbrand'' oder ''Instabiles Gebrechen'' gleichzeitig auf einem beliebigen Ziel aktiv sein.');
