INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1611,0,'de','Ihr entsendet eine verderbte Seele in das Ziel,die 405 to 473 Schattenschaden verursacht und 12 sec lang den Schaden aller Eurer Schaden über Zeit verursachenden Effekte auf dem Ziel um 20% erhöht. Endet die Heimsuchung oder wird sie gebannt,kehrt die Seele zu Euch zurück,um Euch um 100% des von ihr verursachten Schadens zu heilen.');
