INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1623,0,'de','Gewährt Hexenmeister und beschworenem Dämon einen Effekt,solange dieser Dämon aktiv ist.<br /><br />Wichtel - Erhöht Euren Feuerschaden um 1% und erhöht Eure kritische Trefferchance mit Feuerzaubern um 1%.<br /><br />Leerwandler - Verringert erlittenen körperlichen Schaden um 2%.<br /><br />Sukkubus - Erhöht Euren Schattenschaden um 1% und erhöht Eure kritische Trefferchance mit Schattenzaubern um 1%.<br /><br />Teufelsjäger - Verringert jeglichen erlittenen Zauberschaden um 2%.<br /><br />Teufelswache - Erhöht jeglichen verursachten Schaden um 1% und verringert jeglichen erlittenen Schaden um 1%.');
