INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1623,2,'de','Gewährt Hexenmeister und beschworenem Dämon einen Effekt,solange dieser Dämon aktiv ist.<br /><br />Wichtel - Erhöht Euren Feuerschaden um 3% und erhöht Eure kritische Trefferchance mit Feuerzaubern um 3%.<br /><br />Leerwandler - Verringert erlittenen körperlichen Schaden um 6%.<br /><br />Sukkubus - Erhöht Euren Schattenschaden um 3% und erhöht Eure kritische Trefferchance mit Schattenzaubern um 3%.<br /><br />Teufelsjäger - Verringert jeglichen erlittenen Zauberschaden um 6%.<br /><br />Teufelswache - Erhöht jeglichen verursachten Schaden um 3% und verringert jeglichen erlittenen Schaden um 3%.');
