INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1628,'de','Seelenverbindung');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1628,0,'de','Bei Aktivierung werden 20% des von Euch erlittenen Schadens auf Euren Wichtel,Leerwandler,Sukkubus,Teufelsjäger,Eure Teufelswache oder Euren unterworfenen Dämon umgelenkt. Dieser Schaden kann nicht vermieden werden. Hält an,solange der Dämon aktiv ist und kontrolliert wird.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1629,'de','Geschmolzener Kern');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1629,0,'de','Erhöht die Effektdauer Eures Zaubers ''Feuerbrand'' um 3 Sek.,zudem habt Ihr eine Chance von 4%,den Effekt ''Geschmolzener Kern'' zu gewinnen,wenn Eurer Zauber ''Verderbnis'' Schaden verursacht. Der Effekt ''Geschmolzener Kern'' verstärkt die Wirkung der 3 innerhalb der nächsten 15 sec gewirkten Zauber ''Verbrennen'' oder ''Seelenfeuer''.<br /><br />Verbrennen - Erhöht den verursachten Schaden um 6% und verringert die Zauberzeit um 10%.<br /><br />Seelenfeuer - Erhöht den verursachten Schaden um 6% und erhöht die kritische Trefferchance um 5%.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1629,1,'de','Erhöht die Effektdauer Eures Zaubers ''Feuerbrand'' um 6 Sek.,zudem habt Ihr eine Chance von 8%,den Effekt ''Geschmolzener Kern'' zu gewinnen,wenn Eurer Zauber ''Verderbnis'' Schaden verursacht. Der Effekt ''Geschmolzener Kern'' verstärkt die Wirkung der 3 innerhalb der nächsten 15 sec gewirkten Zauber ''Verbrennen'' oder ''Seelenfeuer''.<br /><br />Verbrennen - Erhöht den verursachten Schaden um 12% und verringert die Zauberzeit um 20%.<br /><br />Seelenfeuer - Erhöht den verursachten Schaden um 12% und erhöht die kritische Trefferchance um 10%.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1629,2,'de','Erhöht die Effektdauer Eures Zaubers ''Feuerbrand'' um 9 Sek.,zudem habt Ihr eine Chance von 12%,den Effekt ''Geschmolzener Kern'' zu gewinnen,wenn Eurer Zauber ''Verderbnis'' Schaden verursacht. Der Effekt ''Geschmolzener Kern'' verstärkt die Wirkung der 3 innerhalb der nächsten 15 sec gewirkten Zauber ''Verbrennen'' oder ''Seelenfeuer''.<br /><br />Verbrennen - Erhöht den verursachten Schaden um 18% und verringert die Zauberzeit um 30%.<br /><br />Seelenfeuer - Erhöht den verursachten Schaden um 18% und erhöht die kritische Trefferchance um 15%.');
