INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1634,'de','Dämonische Energie');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1634,0,'de','Erfüllt den beschworenen Dämon des Hexenmeisters mit Macht.<br /><br />Wichtel - Erhöht die kritische Zaubertrefferchance des Wichtels 30 sec lang um 20%.<br /><br />Leerwandler - Erhöht die Gesundheit des Leerwandlers um 20% und die durch seine Angriffe und Zauber erzeugte Bedrohung um 20%. Hält 20 sec lang an.<br /><br />Sukkubus und Inkubus - Lässt den Dämon sofort in einer verbesserten Unsichtbarkeit verschwinden. Das Verschwinden entfernt alle Betäubungen,Verlangsamungen und bewegungseinschränkenden Effekte vom Dämon.<br /><br />Teufelsjäger - Entfernt sofort alle magischen Effekte vom Teufelsjäger.<br /><br />Teufelswache - Erhöht das Angriffstempo der Teufelswache um 20%,bricht alle Betäubungen,Verlangsamungen und bewegungseinschränkende Effekte ab und macht die Teufelswache gegen sie immun. Hält 15 sec lang an.');
