INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1638,'de','Dämonischer Pakt');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1638,0,'de','Erhöht Euren Zauberschaden um 2% und die kritischen Treffer Eures Begleiters belegen alle Gruppen- oder Schlachtzugsmitglieder mit dem Effekt ''Dämonischer Pakt''. Der dämonische Pakt erhöht 45 sec lang die Zaubermacht um 2% Eures Zauberschadens. Dieser Effekt hat eine Abklingzeit von 1 Sek. Unterworfene Dämonen können diesen Effekt nicht auslösen.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1638,1,'de','Erhöht Euren Zauberschaden um 4% und die kritischen Treffer Eures Begleiters belegen alle Gruppen- oder Schlachtzugsmitglieder mit dem Effekt ''Dämonischer Pakt''. Der dämonische Pakt erhöht 45 sec lang die Zaubermacht um 4% Eures Zauberschadens. Dieser Effekt hat eine Abklingzeit von 1 Sek. Unterworfene Dämonen können diesen Effekt nicht auslösen.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1638,2,'de','Erhöht Euren Zauberschaden um 6% und die kritischen Treffer Eures Begleiters belegen alle Gruppen- oder Schlachtzugsmitglieder mit dem Effekt ''Dämonischer Pakt''. Der dämonische Pakt erhöht 45 sec lang die Zaubermacht um 6% Eures Zauberschadens. Dieser Effekt hat eine Abklingzeit von 1 Sek. Unterworfene Dämonen können diesen Effekt nicht auslösen.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1638,3,'de','Erhöht Euren Zauberschaden um 8% und die kritischen Treffer Eures Begleiters belegen alle Gruppen- oder Schlachtzugsmitglieder mit dem Effekt ''Dämonischer Pakt''. Der dämonische Pakt erhöht 45 sec lang die Zaubermacht um 8% Eures Zauberschadens. Dieser Effekt hat eine Abklingzeit von 1 Sek. Unterworfene Dämonen können diesen Effekt nicht auslösen.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1638,4,'de','Erhöht Euren Zauberschaden um 10% und die kritischen Treffer Eures Begleiters belegen alle Gruppen- oder Schlachtzugsmitglieder mit dem Effekt ''Dämonischer Pakt''. Der dämonische Pakt erhöht 45 sec lang die Zaubermacht um 10% Eures Zauberschadens. Dieser Effekt hat eine Abklingzeit von 1 Sek. Unterworfene Dämonen können diesen Effekt nicht auslösen.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1639,'de','Metamorphose');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1639,0,'de','Ihr verwandelt Euch 30 sec lang in einen Dämon. Diese Gestalt erhöht Eure Rüstung um 600%,Euren Schaden um 20% und die Chance,einen kritischen Nahkampftreffer zu erleiden,wird um 6% verringert. Die Dauer auf Euch wirkender Betäubungs- und Verlangsamungseffekte wird um 50% verringert. Zusätzlich zu Euren Fähigkeiten gewinnt Ihr einige einzigartige Dämonenfähigkeiten. 3 Minuten Abklingzeit.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1640,'de','Dezimierung');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1640,0,'de','Wenn Ihr die Zauber ''Schattenblitz'',''Verbrennen'' oder ''Seelenfeuer'' auf ein Ziel wirkt,das weniger als 35% Gesundheit besitzt,wird die Zauberzeit Eurer nächsten Wirkens von ''Seelenfeuer'' 10 sec lang um 20% verringert. Wird ''Seelenfeuer'' gewirkt'',während Ihr unter dem Effekt von ''Dezimierung'' steht,kostet der Zauber keinen Seelensplitter.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1640,1,'de','Wenn Ihr die Zauber ''Schattenblitz'',''Verbrennen'' oder ''Seelenfeuer'' auf ein Ziel wirkt,das weniger als 35% Gesundheit besitzt,wird die Zauberzeit Eurer nächsten Wirkens von ''Seelenfeuer'' 10 sec lang um 40% verringert. Wird ''Seelenfeuer'' gewirkt'',während Ihr unter dem Effekt von ''Dezimierung'' steht,kostet der Zauber keinen Seelensplitter.');
