INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1693,0,'de','Greift sofort bis zu 4 nahe Ziele an. Für die nächsten 6 sec werdet Ihr alle 1 Sek. einen Wirbelwindangriff durchführen. Während ''Klingensturm'' aktiv ist,könnt Ihr Euch bewegen,aber während dieser Zeit keine anderen Fähigkeiten einsetzen. Ihr fühlt weder Mitleid,noch Bedauern oder Furcht und es gibt keine Möglichkeit,Euch aufzuhalten,es sei denn,Ihr werdet getötet.');
