INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1732,'de','Wachsamkeit');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1732,0,'de','Fokussiert Euren schützenden Blick auf ein Gruppen- oder Schlachtzugsmitglied,verringert so seinen erlittenen Schaden um 3% und überträgt <!--sp63326:0-->10<!--sp63326-->% seiner erzeugten Bedrohung auf Euch. Zusätzlich wird jedes Mal,wenn das Ziel von einem Angriff getroffen wird,die Abklingzeit Eurer Fähigkeit ''Spott'' beendet. Hält 30 min lang an. Dieser Effekt kann nur auf jeweils einem Ziel wirken.');
