INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1831,4,'de','Eure automatischen Angriffe verursachen zusätzlich 20% Schattenschaden.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1832,'de','Heimtückische Stöße');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1832,0,'de','Die kritische Trefferchance Eurer Fähigkeiten ''Seuchenstoß'' und ''Geißelstoß'' wird um 3%,ihr kritischer Schadensbonus um 15% erhöht.');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1832,1,'de','Die kritische Trefferchance Eurer Fähigkeiten ''Seuchenstoß'' und ''Geißelstoß'' wird um 6%,ihr kritischer Schadensbonus um 30% erhöht.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1833,'de','Ghulfuror');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1833,0,'de','Gewährt Eurem Begleiter 30 sec lang 25% Tempo und heilt ihn während der Dauer des Effektes um 60% seiner Gesundheit.');
INSERT OR IGNORE INTO talent_names ("talentId","languageCode","name") VALUES (1834,'de','Geißelstoß');
INSERT OR IGNORE INTO rank_descriptions ("talentId","rank","languageCode","description") VALUES (1834,0,'de','Ein unheiliger Stoß,der 70% Waffenschaden als körperlichen Schaden plus 238 verursacht. Für jede Eurer auf das Ziel wirkenden Krankheiten fügt Ihr zusätzlich 12% des verursachten körperlichen Schadens als Schattenschaden zu.');
